"""Run the WS-03 strength review and write WS03_STRENGTH.md plus the regression baseline tests/strength_baseline.json."""
import json
import w3_strength_review as R

ORDER = ["frame", "hinge", "arm", "gen", "wing", "abuse", "creep"]


def main():
    rows = R.run()
    base = {R.row_key(r): round(r["fs"], 3) for r in rows}
    json.dump(base, open("tests/strength_baseline.json", "w"), indent=1, sort_keys=True)
    low = [r for r in rows if r["fs"] < r["min"]]
    L = ["# WS-03 strength and robustness review", "",
         "Generated by `w3_strength_report.py` from the live geometry (`w3_strength_review.py`; solver validated by `w3_strength_validate.py`, see below). Car 2.2 kg, front share 64 %.", "",
         "## Loads", "",
         f"- static axle loads: front {R.WF:.1f} N, rear {R.WR:.1f} N; **3 g on one front wheel = {R.NF:.1f} N** (3 x its static half-axle load; the whole front axle landing on one wheel, {2*R.NF:.1f} N, is an abuse case); 3 g on the rear wheel {R.NR:.1f} N",
         f"- 1.5 g cornering: lateral {R.FYF:.1f} N on the outer front wheel, {R.FYR:.1f} N on the rear wheel;  2 g braking: {R.FXF:.1f} N per front wheel, {R.FXR:.1f} N rear (88/12 % dynamic split)",
         f"- tyres 112 x 62 mm: contact patch {R.RT:.0f} mm below the axle, wheel centre {R.YW:.1f} mm from the centre line, i.e. about 61 mm outboard of the arm's bearing pair (18 mm apart): the vertical load makes a couple of {R.NF*61/18:.0f} N on the two arm planes",
         f"- lean servo stall {R.SERVO_LEAN/98.1/10:.1f} kg.cm = {R.SERVO_LEAN/1000:.2f} N.m; steering servo stall 12 kg.cm; rear shock force at 3 g {R.INFO['rear_Fs3g']:.0f} N (wheel-to-shock ratio {R.INFO['rear_lever']:.2f}); spring preload 10 N",
         f"- wing: 40 km/h, q = {R.INFO['wing']['q_Pa']:.0f} Pa, plan area {R.INFO['wing']['area_m2']*1e4:.0f} cm2, CL 1.3 -> {R.INFO['wing']['lift_N']:.1f} N downforce, drag {R.INFO['wing']['drag_N']:.2f} N, x1.5 g; wing mass 70 g",
         f"- 1 m drop on the rear wheel: rear share 0.79 kg, 33 mm total stopping travel -> {R.INFO['drop']['F']:.0f} N ({R.INFO['drop']['g_equiv']:.0f} g on the rear wheel); a flat drop is survived from about {R.INFO['drop']['h_safe_mm']/1000:.2f} m",
         "", "## Material assumptions (printed PETG)", "",
         f"in-plane (along the print line) design stress {R.SIP:.0f} MPa; across layers {R.SZ:.0f} MPa (50 %); a tube's allowable follows its angle to the bed normal; stress concentration x{R.KT} at every node/notch; "
         f"ultimate = {R.ULT} x design (drop case only); sustained loads (shock preload, weight) derated x{R.CREEP}; thread pull-out 6 MPa on d x engagement; steel pins 400 MPa yield; E = 1500 MPa.", "",
         "## Validation", "",
         "The review FE solver was re-run on the OLD `w3_strength.py` models (old loads, old restraints, 25 MPa, no stress concentration): front arm 3.81, rear arm 4.30, frame 2.52, matching the previous 3.8 / 4.3 / 2.5 "
         "(`python w3_strength_validate.py`). The new, lower numbers therefore come from the changed inputs, not from the solver: heavier car (2.2 vs 1.6 kg), single-wheel 3 g, the wheel-offset couple that the old front-arm model left out "
         f"(front arm 3 g bump: {R.INFO['front_bump_no_couple_fs']:.1f} without the couple, {[r['fs'] for r in rows if r['case']=='3 g bump, one front wheel' and r['part'].startswith('Front arm (')][0]:.2f} with it), real pivot/lug restraints instead of a clamped root, "
         "layer-direction allowables, x1.5 concentration, and the 56 mm contact lever. Hand-check rows that did not change (tie rod 7.3) still match the old table.", "",
         "## Results", "", "| part | load case | stress MPa | allowable MPa | FS | min | verdict | print orientation |", "|---|---|---|---|---|---|---|---|"]
    for g in ORDER:
        for r in rows:
            if r["group"] == g:
                v = "ok" if r["fs"] >= r["min"] else "**BELOW**"
                fs = f"{r['fs']:.2f}" if r["fs"] < 100 else ">100"
                L.append(f"| {r['part']} | {r['case']}{' - ' + r['note'] if r['note'] else ''} | {r['stress']:.1f} | {r['allow']:.1f} | {fs} | {r['min']:.1f} | {v} | {r['orient']} |")
    L += ["", f"## Below their minimum ({len(low)} of {len(rows)} rows)", "", "See `WS03_STRENGTH_FIXES.md` for the geometry fixes in priority order.", ""]
    L += [f"- {r['part']}: {r['case']} - FS {r['fs']:.2f} (min {r['min']:.1f})" for r in sorted(low, key=lambda r: r["fs"] / r["min"])]
    L += ["", "Frame members removed from the FE because the motor can opens the hoop: " + ", ".join(R.INFO.get("frame_removed", [])) + ".",
          f"Assumed (not in the CAD): {R.EAR_SHARE:.0%} of the front arm's pivot reaction enters the cage through the servo-ear plate, the rest goes into the base plate through the housing bolts; "
          "pivot pin size 3 mm steel inferred from the 3.4 mm pad hole; skin + wing 0.25 kg. Frame feet are modelled as pinned (translations fixed)."]
    L += ["", "## Decisions", "", "- "+"Accepted abuse case: the rear swing arm's 1 m drop onto the rear wheel (FS 0.41 against 1.0) stays a documented xfail. A 1 m drop puts about 7.8 J into the rear wheel; the shock and tyre absorb under 1 J, so no printed arm survives it. The arm is good for a flat drop of about 0.1 to 0.15 m: do not drop-test the rear. A stock progressive bump rubber on the rear shock shaft (see the BOM) softens the bottom-out.", "- "+'The ballast and small-mass numbers behind the 64.4 % front share (42 g tungsten plate, 8 g printed carrier and lid, wing and tail at 8 % infill, receiver, wires, bump rubber) are estimates: weigh the real parts and update the inventory in `w3_mass.py` before trusting the front share.']
    open("WS03_STRENGTH.md", "w").write("\n".join(L) + "\n")
    print(len(rows), "rows,", len(low), "below minimum")


if __name__ == "__main__":
    main()
